/**
 * Tests for no-unsafe-copy-from
 * CWE-73 — Prevent unsafe COPY FROM usage with dynamic file paths, which can lead to arbitrary file read/RCE.
 *
 * Generated by: node scripts/generate-rule-tests.mjs
 * Standard: Engineering Standards §5 (side-by-side), §6 (≥5 valid + ≥5 invalid), §8 (RuleTester at describe level)
 */
import { RuleTester } from '@typescript-eslint/rule-tester';
import { describe, it, afterAll } from 'vitest';
import parser from '@typescript-eslint/parser';
import { noUnsafeCopyFrom } from './index';

/**
 * Every fixture imports a PostgreSQL client, because the rule now abstains in
 * files that use no PostgreSQL at all. Wrapping the arrays rather than editing
 * each fixture means one cannot be left behind — a fixture missing the import
 * would pass vacuously on the gate instead of exercising the detection it was
 * written for.
 */
const withPg = (code: string): string => `import { Pool } from 'pg';\n${code}`;
const pg = <T,>(cases: T[]): T[] =>
  cases.map((c) =>
    typeof c === 'string'
      ? (withPg(c) as T)
      : ({ ...c, code: withPg((c as { code: string }).code) } as T),
  );


RuleTester.afterAll = afterAll;
RuleTester.it = it;
RuleTester.itOnly = it.only;
RuleTester.describe = describe;

const ruleTester = new RuleTester({
  languageOptions: {
    parser,
    ecmaVersion: 2022,
    sourceType: 'module',
    parserOptions: { ecmaFeatures: { jsx: true } },
  },
});

describe('no-unsafe-copy-from', () => {
  describe('Valid Code', () => {
    ruleTester.run('valid - safe patterns', noUnsafeCopyFrom, {
      valid: pg([
        // Unrelated code should not trigger
        {
          name: 'pg is imported but nothing queries',
          code: `const x = 1;`,
        },
        // Array operations are safe
        {
          code: `const arr = [1, 2, 3];`,
        },
        // Non-targeted method calls are safe
        {
          code: `obj.safeMethod();`,
        },
        // Environment variable usage is safe (padding case 4)
        {
          code: `const safe3 = process.env.DB_HOST;`,
        },
        // Environment variable usage is safe (padding case 5)
        {
          code: `const safe4 = process.env.DB_HOST;`,
        },
      ]),
      invalid: [],
    });
  });

  describe('Invalid Code', () => {
    ruleTester.run('invalid - dangerous patterns', noUnsafeCopyFrom, {
      valid: [],
      invalid: pg([
        // Triggers dynamicPath
        {
          name: 'a file path interpolated into COPY FROM',
          code: `client.query(\`COPY users FROM '\${filePath}'\`)`,
          errors: [{ messageId: 'dynamicPath' }],
        },
        // Triggers hardcodedPath
        {
          name: 'a hardcoded server path is a server-side file read',
          code: `client.query("COPY users FROM '/tmp/data.csv'")`,
          errors: [{ messageId: 'hardcodedPath' }],
        },
        // Triggers dynamicPath: string concatenation with COPY FROM
        {
          code: `client.query('COPY users FROM ' + filePath)`,
          errors: [{ messageId: 'dynamicPath' }],
        },
      ]),
    });
  });
});

/** FP/FN review 2026-10 (benchmarks/audits/2026-10-10-fp-fn-postgresql-security.md). */
describe('no-unsafe-copy-from — fp/fn review 2026-10', () => {
  ruleTester.run('CF-1: COPY … TO a server path is a file WRITE', noUnsafeCopyFrom, {
    valid: pg([
      { name: 'COPY TO STDOUT streams to the client and writes no file', code: "client.query('COPY users TO STDOUT WITH CSV');" },
      { name: 'an interpolation in the exported query of COPY TO STDOUT writes no file', code: "client.query(`COPY (SELECT id FROM users WHERE org = ${ORG}) TO STDOUT`);" },
      // A fixed export path is an admin script, as with a fixed FROM path.
      { name: 'a fixed export path is an admin script, as a fixed FROM path is', code: "client.query(\"COPY users TO '/var/lib/postgresql/exports/users.csv' WITH CSV\");" },
      { name: 'an export path built from a constant is fixed', code: "const ORG = 'acme';\nclient.query(`COPY users TO '/exports/${ORG}.csv'`);" },
    ]),
    invalid: pg([
      {
        name: 'a user-chosen export path',
        code: "client.query(`COPY users TO '/var/lib/postgresql/exports/${req.query.name}.csv' WITH CSV`);",
        errors: [{ messageId: 'dynamicWritePath' }],
      },
      {
        name: 'COPY (query) TO a concatenated path',
        code: "client.query('COPY (SELECT * FROM users) TO \\'' + target + '\\'');",
        errors: [{ messageId: 'dynamicWritePath' }],
      },
      {
        name: 'an export statement BEFORE a dynamic read is still read',
        code: "client.query(`COPY a TO STDOUT; COPY b FROM '/data/${file}'`);",
        errors: [{ messageId: 'dynamicPath' }],
      },
      {
        name: 'COPY TO PROGRAM with input',
        code: "client.query(`COPY users TO PROGRAM 'gzip > /tmp/${name}.gz'`);",
        errors: [{ messageId: 'dynamicWritePath' }],
      },
    ]),
  });
});
